import {makeOddRound} from '../logic.js';import {gameFrame,roundFlow,shape} from '../ui.js';
export function mountGame(root,c){const flow=roundFlow(root,c);function next(){flow.next();const r=makeOddRound(c.difficulty);const area=gameFrame(root,'Find the odd one out','One arrow points in a different direction.');area.innerHTML=`<div class="tile-grid odd-board" style="--cols:${Math.sqrt(r.items.length)}">${r.items.map((rotation,i)=>`<button data-i="${i}" aria-label="Arrow rotated ${rotation} degrees, tile ${i+1}">${shape('arrow','#517aad',c.difficulty==='hard'?34:44,rotation)}</button>`).join('')}</div>`;area.querySelectorAll('button').forEach(b=>b.onclick=()=>{flow.answer(+b.dataset.i===r.answer,`Tile ${r.answer+1} is rotated differently.`,next);area.querySelector(`[data-i="${r.answer}"]`).classList.add('solution-tile');});}next();return {dispose(){}};}
